const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');
function game(random,options={}){
  const storage=options.storage||new Map();
  const elements=new Map(),listeners={};
  const context=new Proxy({}, {get:(target,key)=>key in target?target[key]:()=>{},set:(target,key,value)=>(target[key]=value,true)});
  function element(id){if(!elements.has(id))elements.set(id,{clientWidth:480,clientHeight:270,hidden:false,textContent:'',classList:{toggle(){},add(){},remove(){}},setAttribute(){},listeners:{},addEventListener(name,cb){this.listeners[name]=cb;},focus(){},getContext:()=>context});return elements.get(id);}
  const gameMath=Object.create(Math);if(random)gameMath.random=random;
  const sandbox={console,Math:gameMath,AbortController,HTMLButtonElement:class{},matchMedia:()=>({matches:!!options.reduced}),ResizeObserver:class{constructor(cb){this.cb=cb}observe(){this.cb()}},localStorage:{getItem:key=>{if(options.denied)throw Error('denied');return storage.get(key)??null;},setItem:(key,value)=>{if(options.denied)throw Error('denied');storage.set(key,value);}},requestAnimationFrame(){},document:{getElementById:element,addEventListener:(name,cb)=>listeners[name]=cb},window:{AudioContext:options.audioContext,addEventListener(){}}};
  let source=fs.readFileSync(path.join(__dirname,'../dist/game.js'),'utf8');
  source=source.replace('  window.pixelFlight={',`  window.testGame={drawBird,addScore,continueRun,update,draw,enemySettings,createEnemy,updateEnemies,pickupPosition,plannedPipe,rollClockTier,clockTier,createPipe,updatePipeMotion,motionSettings,resize,inspect:()=>({rocketThrust,rocketFlip,lives,lifeSpawn,reviveTime,checkpoint,pipes,enemies,enemySpawn,pickups,bombs,bombCapacity,capacitySpawn,blasts,particles,bombSpawn,spawn,bird,scrollSpeed,difficultyLevel,slowUnlocked,slowSpawn,slowFeedback}),setup:(s)=>{if(s.lives!==undefined){lives=s.lives;livesUI();}if(s.lifeSpawn!==undefined)lifeSpawn=s.lifeSpawn;if(s.reviveTime!==undefined)reviveTime=s.reviveTime;if(s.score!==undefined){score=s.score;difficultyLevel=score;pipesPassed=score;}if(s.passed!==undefined)pipesPassed=s.passed;if(s.level!==undefined)difficultyLevel=s.level;if(s.height!==undefined)H=s.height;if(s.scrollSpeed!==undefined)scrollSpeed=s.scrollSpeed;if(s.slowUnlocked!==undefined)slowUnlocked=s.slowUnlocked;if(s.slowSpawn!==undefined)slowSpawn=s.slowSpawn;if(s.enemies)enemies=s.enemies;if(s.enemySpawn!==undefined)enemySpawn=s.enemySpawn;if(s.bombs!==undefined)bombs=s.bombs;if(s.pipes)pipes=s.pipes;if(s.pickups)pickups=s.pickups;if(s.spawn!==undefined)spawn=s.spawn;if(s.bombSpawn!==undefined)bombSpawn=s.bombSpawn;if(s.capacitySpawn!==undefined)capacitySpawn=s.capacitySpawn;if(s.bird)bird=s.bird;}};\n  window.pixelFlight={`);
  vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../dist/version.js'),'utf8'),sandbox);
  vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../dist/world.js'),'utf8'),sandbox);
  vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../dist/routes.js'),'utf8'),sandbox);
  vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../dist/cosmetics.js'),'utf8'),sandbox);
  vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../dist/powerup-art.js'),'utf8'),sandbox);
  vm.runInNewContext(source,sandbox);
  return {context,cosmetics:sandbox.window.flightCosmetics,storage,routes:sandbox.window.flightRoutes,elements,api:sandbox.window.pixelFlight,world:sandbox.window.flightWorld,scene:sandbox.window.testGame,keydown:(code,repeat=false)=>listeners.keydown({code,repeat,target:{},preventDefault(){}})};
}
test('lives start at three, cap at six, and heart pickups never award points or alter difficulty',()=>{
  const g=game(()=>.5);g.api.start();assert.equal(g.api.getState().lives,3);assert.equal(g.api.getState().maxLives,6);
  const b=g.scene.inspect().bird;g.scene.setup({pickups:Array.from({length:5},()=>({kind:'life',x:b.x,y:b.y,phase:0})),spawn:100,bombSpawn:100});g.scene.update(0);
  assert.equal(g.api.getState().lives,6);assert.equal(g.api.getState().score,0);assert.equal(g.api.getState().difficulty,0);assert.equal(g.scene.inspect().pickups.length,0);
  g.api.start();assert.equal(g.api.getState().lives,3);assert.equal(g.api.getState().checkpoint,0);
});
test('the first score milestones grant one life each, including crossed bonus thresholds, only once per run',()=>{
  const g=game();g.api.start();g.scene.setup({score:495,passed:4,level:4});g.scene.addScore(10);assert.equal(g.api.getState().lives,4);assert.equal(g.api.getState().pipesPassed,4);
  g.scene.setup({score:999});g.scene.addScore(60);assert.equal(g.api.getState().lives,5);
  g.scene.setup({score:495});g.scene.addScore(10);g.scene.setup({score:999});g.scene.addScore(1);assert.equal(g.api.getState().lives,5);
  g.api.start();g.scene.setup({score:499});g.scene.addScore(1);assert.equal(g.api.getState().lives,4);
  g.scene.setup({lives:6,score:999});g.scene.addScore(1);g.scene.setup({lives:5,score:999});g.scene.addScore(1);assert.equal(g.api.getState().lives,5);
});
function loseLife(g){const b=g.scene.inspect().bird;g.scene.setup({pipes:[],enemies:[],pickups:[],spawn:100,bombSpawn:100,enemySpawn:100,reviveTime:0,bird:{x:b.x,y:245+(g.elements.get('frame').clientHeight>300?114:0),v:0}});g.scene.update(0);}
test('one collision consumes exactly one life and continue restores the initial checkpoint without restarting lives',()=>{
  const g=game();g.api.start();g.scene.setup({score:70,passed:30,level:60,bombs:2});loseLife(g);assert.equal(g.api.getState().lives,2);assert.equal(g.api.getState().canContinue,true);
  g.scene.update(0);g.scene.update(.6);assert.equal(g.api.getState().lives,2);assert.ok(g.scene.continueRun());
  const s=g.api.getState();assert.equal(s.state,'playing');assert.equal(s.lives,2);assert.equal(s.score,0);assert.equal(s.pipesPassed,0);assert.equal(s.difficulty,0);assert.equal(s.bombs,0);assert.ok(s.shieldRemaining>=1.8);
  assert.equal(g.scene.continueRun(),false);assert.ok(g.scene.inspect().spawn>=1);assert.ok(g.scene.inspect().enemySpawn>=3);
  loseLife(g);g.scene.update(.6);g.elements.get('play').listeners.click();assert.equal(g.api.getState().lives,1);assert.equal(g.api.getState().state,'playing');
  loseLife(g);g.scene.update(.6);assert.equal(g.api.getState().lives,0);assert.equal(g.api.getState().canContinue,false);assert.equal(g.scene.continueRun(),false);g.elements.get('play').listeners.click();assert.equal(g.api.getState().lives,3);
});
test('a checkpoint every 50 actual pipes restores score, clocks, inventory, day and biome on desktop and mobile',()=>{
  for(const [width,height] of [[480,270],[288,384]]){
    const g=game(()=>.99);g.elements.get('frame').clientWidth=width;g.elements.get('frame').clientHeight=height;g.scene.resize();g.api.start();
    for(let i=0;i<49;i++)passPipe(g);assert.equal(g.api.getState().checkpoint,0);
    g.scene.setup({bombs:2});passPipe(g);const saved=g.api.getState(),world=JSON.stringify(g.world.snapshot());assert.equal(saved.checkpoint,50);assert.equal(g.elements.get('checkpoint-count').textContent,'CHACKPOINT 50');
    const b=g.scene.inspect().bird;g.scene.setup({pickups:[{kind:'life',x:b.x,y:b.y,phase:0}],spawn:100});g.scene.update(0);assert.equal(g.api.getState().lives,4);
    for(let i=0;i<8;i++)passPipe(g);g.scene.setup({level:0,bombs:0});loseLife(g);g.scene.update(.6);assert.ok(g.scene.continueRun());const restored=g.api.getState();
    for(const key of ['score','pipesPassed','difficulty','days','background','moment','bombs','bombCapacity','bonusPoints'])assert.equal(restored[key],saved[key],key);
    assert.equal(restored.lives,3);assert.equal(JSON.stringify(g.world.snapshot()),world);assert.equal(g.scene.inspect().pipes.length,0);assert.equal(g.scene.inspect().enemies.length,0);
    for(let i=0;i<50;i++)passPipe(g);assert.equal(g.api.getState().checkpoint,100);
  }
});
test('heart spawning stays irregular, safe, unique, paused with the game and absent at full health',()=>{
  let seed=400;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();const intervals=new Set();
  for(let i=0;i<8;i++){g.scene.setup({lifeSpawn:0,pipes:[],pickups:[],spawn:0,bombSpawn:100});g.scene.update(0);const hearts=g.scene.inspect().pickups.filter(p=>p.kind==='life');assert.equal(hearts.length,1);assert.ok(hearts[0].y>=22&&hearts[0].y<=200);const interval=g.scene.inspect().lifeSpawn;assert.ok(interval>=60&&interval<=90);intervals.add(interval);g.scene.setup({lifeSpawn:0,spawn:0});g.scene.update(0);assert.equal(g.scene.inspect().pickups.filter(p=>p.kind==='life').length,1);}
  assert.ok(intervals.size>1);g.scene.setup({lifeSpawn:5});g.api.pause();g.scene.update(2);assert.equal(g.scene.inspect().lifeSpawn,5);g.api.pause();g.scene.setup({lives:6,pickups:[],lifeSpawn:0,spawn:0,pipes:[]});g.scene.update(0);assert.equal(g.scene.inspect().pickups.filter(p=>p.kind==='life').length,0);
});
test('checkpoint flags follow the 50th surviving pipe and bombs cannot activate a checkpoint',()=>{
  const g=game(()=>.5);g.api.start();const labels=[];g.context.fillText=text=>labels.push(text);g.scene.setup({passed:48,pipes:[{x:200,y:60,gap:80},{x:400,y:60,gap:80}],bombs:1});g.scene.draw();assert.ok(labels.includes('50'));
  g.api.detonate();assert.equal(g.api.getState().checkpoint,0);g.scene.setup({pipes:[{x:400,y:60,gap:80}]});labels.length=0;g.scene.draw();assert.ok(!labels.includes('50'));
  passPipe(g);passPipe(g);assert.equal(g.api.getState().checkpoint,50);
});
test('respawn protection freezes on pause, prevents immediate floor deaths, and does not renew on repeated input',()=>{
  const g=game();g.api.start();loseLife(g);g.scene.update(.6);g.keydown('Space');assert.equal(g.api.getState().lives,2);const before=g.api.getState().shieldRemaining;
  g.api.pause();g.scene.update(5);assert.equal(g.api.getState().shieldRemaining,before);g.api.pause();g.scene.setup({bird:{x:129,y:245,v:20}});g.scene.update(.1);assert.equal(g.api.getState().state,'playing');assert.equal(g.api.getState().lives,2);assert.ok(g.scene.inspect().bird.y<242);
  g.scene.setup({reviveTime:0,bird:{x:129,y:245,v:20}});g.scene.update(0);assert.equal(g.api.getState().lives,1);
});
test('every life loss retains the complete 190-point best run when the next attempt scores zero',()=>{
  const g=game();g.api.start();for(let i=0;i<10;i++)passPipe(g);
  const b=g.scene.inspect().bird;
  for(let cycle=0;cycle<6;cycle++){
    g.scene.setup({pipes:[],pickups:Array.from({length:3},()=>({kind:'bomb',x:b.x,y:b.y,phase:0})),spawn:100});g.scene.update(0);
    for(let i=0;i<3;i++)assert.ok(g.api.detonate());
  }
  assert.equal(g.api.getState().score,190);assert.equal(g.api.getState().checkpoint,0);loseLife(g);
  const ids=['final-score','final-days','final-pipes','final-bonus','final-speed','bonus-breakdown'];
  const first=ids.map(id=>g.elements.get(id).textContent);assert.equal(first[0],'190');assert.equal(first[2],'10');assert.equal(first[3],'180');
  g.scene.update(.6);assert.ok(g.scene.continueRun());assert.equal(g.api.getState().score,0);loseLife(g);
  assert.equal(g.api.getState().lives,1);assert.equal(g.api.getState().score,0);assert.deepEqual(ids.map(id=>g.elements.get(id).textContent),first);
});
test('intermediate summaries update for a stronger run while independent records can improve on a weaker run',()=>{
  const g=game();g.api.start();for(let i=0;i<10;i++)passPipe(g);loseLife(g);g.scene.update(.6);g.scene.continueRun();
  for(let i=0;i<15;i++)passPipe(g);const b=g.scene.inspect().bird;
  g.scene.setup({pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0}],spawn:100});g.scene.update(0);loseLife(g);
  assert.equal(g.api.getState().lives,1);assert.equal(g.elements.get('final-score').textContent,'25');assert.equal(g.elements.get('final-pipes').textContent,'15');
  g.scene.update(.6);g.scene.continueRun();for(let i=0;i<20;i++)passPipe(g);loseLife(g);
  assert.equal(g.elements.get('final-score').textContent,'25');assert.equal(g.elements.get('final-pipes').textContent,'15');assert.equal(g.elements.get('final-bonus').textContent,'10');assert.equal(g.api.getState().records.pipes,20);assert.equal(g.elements.get('best-pipes').textContent,'20');
  g.api.start();g.scene.setup({lives:2});passPipe(g);loseLife(g);assert.equal(g.elements.get('final-score').textContent,'1');
});
test('the final summary uses one coherent best attempt even after checkpoint retries and a weaker final life',()=>{
  const g=game();g.api.start();for(let i=0;i<50;i++)passPipe(g);
  for(let i=0;i<10;i++)passPipe(g);const b=g.scene.inspect().bird;
  g.scene.setup({pickups:[{kind:'slow',clockTier:'legendary',x:b.x,y:b.y,phase:0}],spawn:100});g.scene.update(0);loseLife(g);g.scene.update(.6);
  const first=JSON.stringify(g.api.getState().bestAttempt);assert.equal(g.api.getState().bestAttempt.score,120);assert.ok(g.scene.continueRun());
  for(let i=0;i<30;i++)passPipe(g);loseLife(g);g.scene.update(.6);assert.ok(g.scene.continueRun());
  for(let i=0;i<2;i++)passPipe(g);loseLife(g);
  assert.equal(g.api.getState().lives,0);assert.equal(JSON.stringify(g.api.getState().bestAttempt),first);assert.equal(g.api.getState().score,52);
  assert.equal(g.elements.get('final-score').textContent,'120');assert.equal(g.elements.get('final-pipes').textContent,'60');assert.equal(g.elements.get('final-days').textContent,'2');assert.equal(g.elements.get('final-bonus').textContent,'60');assert.equal(g.elements.get('bonus-breakdown').textContent,'Bombas 0 · Relojes 60 · Rasantes 0');assert.equal(g.elements.get('final-speed').textContent,'×1,60');
  assert.match(g.elements.get('message').textContent,/120/);g.api.start();assert.equal(g.api.getState().bestAttempt,null);
});
test('the last life can become the best attempt and a new game does not inherit a previous summary',()=>{
  const g=game();g.api.start();for(let i=0;i<5;i++)passPipe(g);loseLife(g);g.scene.update(.6);g.scene.continueRun();
  for(let i=0;i<3;i++)passPipe(g);loseLife(g);g.scene.update(.6);g.scene.continueRun();
  for(let i=0;i<12;i++)passPipe(g);loseLife(g);assert.equal(g.elements.get('final-score').textContent,'12');assert.equal(g.elements.get('final-pipes').textContent,'12');assert.equal(g.api.getState().bestAttempt.score,12);
  g.api.start();g.scene.setup({lives:1});passPipe(g);loseLife(g);assert.equal(g.elements.get('final-score').textContent,'1');assert.equal(g.api.getState().best,12);
});
test('equal-score attempts prefer more pipes and retain that attempt bonus breakdown',()=>{
  const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0}],spawn:100});g.scene.update(0);loseLife(g);g.scene.update(.6);g.scene.continueRun();
  for(let i=0;i<10;i++)passPipe(g);g.scene.setup({lives:1});loseLife(g);assert.equal(g.elements.get('final-score').textContent,'10');assert.equal(g.elements.get('final-pipes').textContent,'10');assert.equal(g.elements.get('final-bonus').textContent,'0');
});
function pointerEvent(overrides={}){return{pointerType:'touch',pointerId:2,isPrimary:false,button:0,prevented:false,stopped:false,preventDefault(){this.prevented=true;},stopPropagation(){this.stopped=true;},...overrides};}
test('two simultaneous touch contacts flap and detonate immediately in either order without a click',()=>{
  for(const order of ['flap-first','bomb-first']){
    const g=game();g.api.start();const b=g.scene.inspect().bird;
    g.scene.setup({bombs:2,bird:{...b,v:80},pipes:[{x:b.x,y:b.y+20,gap:88}],spawn:100});
    const flap=()=>g.elements.get('game').listeners.pointerdown(pointerEvent({pointerId:1,isPrimary:order==='flap-first'}));
    const contact=pointerEvent({isPrimary:order==='bomb-first'}),bomb=()=>g.elements.get('bomb').listeners.pointerdown(contact);
    if(order==='flap-first'){flap();bomb();}else{bomb();flap();}
    assert.equal(g.scene.inspect().bird.v,-145);assert.equal(g.api.getState().bombs,1);assert.equal(g.scene.inspect().pipes.length,0);assert.equal(g.scene.inspect().blasts.length,1);assert.ok(contact.prevented&&contact.stopped);
    g.scene.update(0);assert.equal(g.api.getState().state,'playing');
  }
});
test('pointer compatibility clicks cannot double-spend bombs, including zero-detail touch clicks',()=>{
  for(const pointerType of ['touch','mouse','pen'])for(const detail of [0,1,2]){
    const g=game();g.api.start();g.scene.setup({bombs:3});g.elements.get('bomb').listeners.pointerdown(pointerEvent({pointerType}));
    g.elements.get('bomb').listeners.click(pointerEvent({pointerType,detail}));assert.equal(g.api.getState().bombs,2);assert.equal(g.scene.inspect().blasts.length,1);
  }
});
test('a second bomb contact works while the jumping finger stays down, without autorepeat while held',()=>{
  const g=game();g.api.start();g.scene.setup({bombs:3,spawn:100});
  g.elements.get('game').listeners.pointerdown(pointerEvent({pointerId:1,isPrimary:true}));
  g.elements.get('bomb').listeners.pointerdown(pointerEvent({pointerId:2}));g.scene.update(.1);assert.equal(g.api.getState().bombs,2);
  g.elements.get('bomb').listeners.pointerdown(pointerEvent({pointerId:3}));assert.equal(g.api.getState().bombs,1);assert.equal(g.scene.inspect().blasts.length,2);
});
test('keyboard and assistive click activation remain available and non-primary mouse buttons are ignored',()=>{
  const g=game();g.api.start();g.scene.setup({bombs:3});
  g.elements.get('bomb').listeners.pointerdown(pointerEvent({pointerType:'mouse',button:2}));assert.equal(g.api.getState().bombs,3);
  g.elements.get('bomb').listeners.click(pointerEvent({detail:0,pointerType:''}));assert.equal(g.api.getState().bombs,2);
  g.keydown('KeyX');g.keydown('Enter');assert.equal(g.api.getState().bombs,0);
});
test('empty touch contact sounds only once and pointer input cannot detonate while paused or dead',()=>{
  const a=audioProbe(),g=game(null,{audioContext:a.AudioContext});g.api.start();a.events.length=0;
  g.elements.get('bomb').listeners.pointerdown(pointerEvent());g.elements.get('bomb').listeners.click(pointerEvent({detail:1}));assert.equal(a.events.length,2);
  g.scene.setup({bombs:2});g.api.pause();g.elements.get('bomb').listeners.pointerdown(pointerEvent());assert.equal(g.api.getState().bombs,2);assert.equal(a.events.length,2);
  g.api.pause();loseLife(g);const before=a.events.length;g.elements.get('bomb').listeners.pointerdown(pointerEvent());assert.equal(g.api.getState().bombs,2);assert.equal(a.events.length,before);
});
test('collects at most 3 bombs and starts each round empty',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({pickups:Array.from({length:4},()=>({x:b.x,y:b.y,phase:0}))});g.scene.update(0);assert.equal(g.api.getState().bombs,3);assert.equal(g.scene.inspect().pickups.length,1);g.api.start();assert.equal(g.api.getState().bombs,0);assert.equal(g.scene.inspect().pickups.length,0);});
test('bomb placement stays safe and its next interval is irregular',()=>{const g=game();g.api.start();const delays=new Set();for(let i=0;i<6;i++){g.scene.setup({pipes:[],pickups:[],spawn:0,bombSpawn:0});g.scene.update(0);const {pipes,pickups,bombSpawn}=g.scene.inspect();assert.equal(pickups.length,1);assert.ok(pickups[0].y>=22&&pickups[0].y<=270-28-20);if(pickups[0].placement==='gap')assert.ok(pickups[0].y>=pipes[0].y+22&&pickups[0].y<=pipes[0].y+pipes[0].gap-22);else assert.ok(pickups[0].x+13<pipes[0].x-5);assert.ok(bombSpawn>=5&&bombSpawn<12);delays.add(bombSpawn);}assert.ok(delays.size>1);});
test('detonation immediately clears every visible pipe, keeps offscreen pipes, and gives no points',()=>{const g=game();g.api.start();g.scene.setup({bombs:2,pipes:[{x:-40,y:70,gap:88},{x:125,y:70,gap:88},{x:478,y:70,gap:88},{x:495,y:70,gap:88},{x:-45,y:70,gap:88}]});assert.equal(g.api.detonate(),true);assert.equal(g.api.getState().bombs,1);assert.equal(g.scene.inspect().pipes.length,2);assert.ok(g.scene.inspect().pipes.every(p=>p.x===495||p.x===-45));assert.equal(g.api.getState().score,0);assert.equal(g.scene.inspect().blasts.length,1);assert.ok(g.scene.inspect().particles.length>100);g.scene.draw();});
test('last-minute bomb prevents an otherwise imminent pipe collision',()=>{for(const useBomb of [false,true]){const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({bombs:1,pipes:[{x:b.x,y:b.y+20,gap:88,passed:false}]});if(useBomb)g.api.detonate();g.scene.update(0);assert.equal(g.api.getState().state,useBomb?'playing':'dead');}});
test('X and Enter use one bomb each; held key does not consume more',()=>{const g=game();g.api.start();g.scene.setup({bombs:3});g.keydown('KeyX');assert.equal(g.api.getState().bombs,2);g.keydown('KeyX',true);assert.equal(g.api.getState().bombs,2);g.keydown('Enter');assert.equal(g.api.getState().bombs,1);g.keydown('NumpadEnter');assert.equal(g.api.getState().bombs,0);assert.equal(g.api.detonate(),false);});
test('pause freezes pickups and explosions and cannot spend bombs',()=>{const g=game();g.api.start();g.scene.setup({bombs:2,pickups:[{x:300,y:100,phase:0}]});g.api.detonate();g.api.pause();const before=g.scene.inspect();g.scene.update(.03);assert.equal(g.api.detonate(),false);assert.equal(g.api.getState().bombs,1);assert.equal(before.pickups[0].x,300);assert.equal(before.blasts[0].age,0);});
test('bombs do not prevent ground collisions or activate after death',()=>{const g=game();g.api.start();g.scene.setup({bombs:1,bird:{x:125,y:245,v:0}});g.api.detonate();g.scene.update(0);assert.equal(g.api.getState().state,'dead');g.scene.setup({bombs:1});assert.equal(g.api.detonate(),false);assert.equal(g.api.getState().bombs,1);});

test('difficulty rises per pipe while day and scenery retain 10/20-point milestones',()=>{const g=game();g.api.start();assert.equal(g.api.getState().moment,'amanecer');let previous='bosque';for(let points=10;points<=80;points+=10){const b=g.scene.inspect().bird;g.scene.setup({score:points-1,pipes:[{x:b.x-45,y:b.y-40,gap:88,passed:false}]});g.scene.update(0);const state=g.api.getState();assert.equal(state.score,points);assert.equal(state.difficulty,points);assert.equal(state.moment,['amanecer','día','atardecer','noche'][(points/10)%4]);if(points%20===0){assert.notEqual(state.background,previous);previous=state.background;}else assert.equal(state.background,previous);}g.api.start();assert.equal(g.api.getState().background,'bosque');assert.equal(g.api.getState().moment,'amanecer');assert.equal(g.scene.inspect().scrollSpeed,102);});
test('speed eases up while rest sections widen only newly spawned gaps',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird;const existing={x:350,y:75,gap:88,passed:false};g.scene.setup({score:10,pipes:[existing],spawn:0});g.scene.update(.01);const {pipes,scrollSpeed}=g.scene.inspect();assert.equal(existing.gap,88);assert.ok(pipes[1].gap<102&&pipes[1].gap>96);assert.ok(scrollSpeed>102&&scrollSpeed<106);g.api.pause();g.scene.update(.03);assert.equal(g.scene.inspect().scrollSpeed,scrollSpeed);});
test('all five backgrounds render across the four day phases',()=>{let choice=.1;const g=game(()=>choice);g.api.start();const names=['bosque','montañas','ciudad','desierto','océano'],seen=new Set(['bosque']);for(const target of [1,2,3,4,0]){const current=names.indexOf(g.world.getState().background),options=[0,1,2,3,4].filter(i=>i!==current);choice=(options.indexOf(target)+.1)/4;g.world.advance(20);g.world.update(3);g.scene.draw();seen.add(g.world.getState().background);g.world.advance(10);g.world.update(3);g.scene.draw();g.world.advance(30);g.world.update(3);g.scene.draw();}g.world.reset();g.scene.draw();assert.equal(seen.size,5);});
function passPipe(g){const b=g.scene.inspect().bird;g.scene.setup({pipes:[{x:b.x-45,y:b.y-40,gap:88,passed:false}]});g.scene.update(0);}
function collectSlow(g,count=1){const b=g.scene.inspect().bird;g.scene.setup({pipes:[],pickups:Array.from({length:count},()=>({kind:'slow',x:b.x,y:b.y,phase:0}))});g.scene.update(0);}
test('slowdowns stay locked below 1.25 and unlock exactly on the 25th point',()=>{const g=game();g.api.start();g.scene.setup({score:24,spawn:0,slowSpawn:-1,bombSpawn:100});g.scene.update(0);assert.equal(g.api.getState().speedMultiplier,1.24);assert.equal(g.api.getState().slowUnlocked,false);assert.equal(g.scene.inspect().pickups.length,0);g.scene.setup({score:24});passPipe(g);assert.equal(g.api.getState().score,25);assert.equal(g.api.getState().speedMultiplier,1.25);assert.equal(g.api.getState().slowUnlocked,true);assert.ok(g.scene.inspect().slowSpawn>=24&&g.scene.inspect().slowSpawn<42);});
test('hourglass keeps irregular timing and safe placement, including below 1.25 once unlocked',()=>{const g=game();g.api.start();const times=new Set();for(let i=0;i<6;i++){g.scene.setup({level:2,slowUnlocked:true,spawn:0,slowSpawn:0,bombSpawn:100,pipes:[],pickups:[]});g.scene.update(0);const {pickups,pipes,slowSpawn}=g.scene.inspect();assert.equal(pickups[0].kind,'slow');assert.ok(pickups[0].y>=22&&pickups[0].y<=270-28-20);if(pickups[0].placement==='gap')assert.ok(pickups[0].y>=pipes[0].y+22&&pickups[0].y<=pipes[0].y+pipes[0].gap-22);else assert.ok(pickups[0].x+13<pipes[0].x-5);assert.ok(slowSpawn>=24&&slowSpawn<42);times.add(slowSpawn);}assert.ok(times.size>1);g.scene.draw();});
test('collecting an hourglass reduces current speed by 15%, adds 40 points without advancing scenery',()=>{const g=game();g.api.start();g.scene.setup({score:79,level:36,bombs:3,slowUnlocked:true});const before=g.api.getState();collectSlow(g);const after=g.api.getState();assert.equal(after.difficulty,15.6);assert.equal(after.speedMultiplier,1.156);assert.equal(after.score,119);assert.equal(after.bombs,3);assert.equal(after.background,before.background);assert.equal(after.moment,before.moment);assert.equal(after.pipesPassed,before.pipesPassed);assert.equal(g.scene.inspect().pickups.length,0);});
test('slowdowns clamp to baseline, clear remaining hourglasses, and can resume after the next passed pipe',()=>{const g=game();g.api.start();g.scene.setup({score:25,level:2,slowUnlocked:true});collectSlow(g,4);assert.equal(g.api.getState().difficulty,0);assert.equal(g.api.getState().speedMultiplier,1);assert.equal(g.api.getState().score,65);assert.equal(g.scene.inspect().pickups.length,0);g.scene.setup({spawn:0,slowSpawn:-1,bombSpawn:100});g.scene.update(0);assert.equal(g.scene.inspect().pickups.length,0);g.scene.setup({score:59,level:0});passPipe(g);assert.equal(g.api.getState().difficulty,1);assert.equal(g.api.getState().slowUnlocked,true);g.scene.setup({spawn:0,slowSpawn:0,bombSpawn:100,pipes:[]});g.scene.update(0);assert.equal(g.scene.inspect().pickups[0].kind,'slow');});
test('slowing smoothly reduces actual speed and safely widens existing narrow gaps',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird,pipe={x:350,y:70,gap:76,passed:false};g.scene.setup({score:70,level:36,slowUnlocked:true,scrollSpeed:138.72,pipes:[pipe],pickups:[{kind:'slow',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().difficulty,15.6);assert.ok(pipe.gap>76);assert.ok(pipe.y<70);assert.equal(pipe.y+pipe.gap/2,108);g.scene.update(.03);assert.ok(g.scene.inspect().scrollSpeed<138.72&&g.scene.inspect().scrollSpeed>118.32);});
test('pause freezes slowdowns and restarting resets unlock, level and speed',()=>{const g=game();g.api.start();g.scene.setup({score:25,slowUnlocked:true,slowSpawn:4});const b=g.scene.inspect().bird;g.scene.setup({pickups:[{kind:'slow',x:b.x,y:b.y,phase:0}]});g.api.pause();g.scene.update(.03);assert.equal(g.api.getState().difficulty,25);assert.equal(g.scene.inspect().slowSpawn,4);g.api.start();assert.equal(g.api.getState().difficulty,0);assert.equal(g.api.getState().speedMultiplier,1);assert.equal(g.api.getState().slowUnlocked,false);assert.equal(g.scene.inspect().pickups.length,0);});
test('in-gap pickups remain possible while an unsafe detour is deferred',()=>{const a=game(()=>.12);a.api.start();const previous={x:300,y:90,gap:88},pipe={x:476,y:90,gap:88};a.scene.setup({level:0});assert.equal(a.scene.pickupPosition(pipe,previous).placement,'gap');a.scene.setup({level:150});assert.equal(a.scene.pickupPosition(pipe,previous),null);const b=game(()=>.05);b.api.start();b.scene.setup({level:100});assert.equal(b.scene.pickupPosition(pipe,previous).placement,'gap');});
test('optional pickup routes stay varied while infeasible placements are deferred',()=>{let seed=91;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();const previous={x:300,y:90,gap:88},pipe={x:476,y:90,gap:88};for(const height of [270,384])for(const level of [0,25,150]){g.scene.setup({height,level});let between=0,offRoute=0;const bins=new Set();for(let i=0;i<80;i++){const p=g.scene.pickupPosition(pipe,previous);if(p?.placement==='between'){between++;bins.add(Math.min(4,Math.floor((p.y-22)/(height-70)*5)));if(p.y<90||p.y>178)offRoute++;}}assert.ok(between>30);assert.ok(offRoute/between>.12);assert.ok(bins.size>=2);}});
test('both bombs and hourglasses use placement outside gaps during real spawning',()=>{for(const kind of ['bomb','slow']){const g=game(()=>.58);g.api.start();g.scene.setup({level:50,slowUnlocked:true,spawn:0,bombSpawn:kind==='bomb'?0:100,slowSpawn:kind==='slow'?0:100,pipes:[{x:320,y:80,gap:88,passed:false}],pickups:[]});g.scene.update(0);const pickup=g.scene.inspect().pickups[0];assert.equal(pickup.kind,kind);assert.equal(pickup.placement,'between');g.scene.draw();}});
test('pickup sprite and bobbing stay clear of pipes and world edges on desktop and mobile',()=>{let seed=73;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();for(const height of [270,384])for(const level of [0,5,15,40,100]){g.scene.setup({height,level});for(let i=0;i<25;i++){const y=38+(i*17)%(height-28-88-76),ny=38+(i*31)%(height-28-88-76),previous={x:300,y,gap:88},pipe={x:476,y:ny,gap:88},p=g.scene.pickupPosition(pipe,previous);if(!p)continue;assert.ok(p.y-19>=0&&p.y+13<height-28);if(p.placement==='gap'){assert.ok(p.y-19>=pipe.y&&p.y+13<=pipe.y+pipe.gap);}else{assert.ok(p.x-13>previous.x+41&&p.x+13<pipe.x-5);assert.ok(p.y>=22&&p.y<=height-28-20);}}}});
test('every passed pipe adds exactly 0.01 speed and an hourglass reverses up to thirty steps',()=>{const g=game();g.api.start();for(let n=1;n<=12;n++){passPipe(g);assert.equal(g.api.getState().difficulty,n);assert.equal(g.api.getState().speedMultiplier,1+n*.01);}collectSlow(g);assert.equal(g.api.getState().difficulty,0);assert.equal(g.api.getState().score,52);passPipe(g);assert.equal(g.api.getState().difficulty,1);assert.equal(g.api.getState().score,53);assert.equal(g.api.getState().speedMultiplier,1.01);});
test('moving pipes begin at effective level 25 and grow in frequency, amplitude and rate',()=>{const g=game(()=>0);g.api.start();g.scene.setup({level:24});assert.equal(g.scene.createPipe(400,88).motion,undefined);assert.equal(g.scene.motionSettings().chance,0);g.scene.setup({level:25});const initial=g.scene.motionSettings(),pipe=g.scene.createPipe(400,88);assert.ok(pipe.motion);g.scene.setup({level:125});const later=g.scene.motionSettings();assert.ok(later.chance>initial.chance&&later.chance<1);assert.ok(later.amplitude>initial.amplitude);assert.ok(later.rate>initial.rate);const h=game(()=>.3);h.api.start();h.scene.setup({level:25});assert.equal(h.scene.createPipe(400,80).motion,undefined);h.scene.setup({level:125});assert.ok(h.scene.createPipe(400,80).motion);});
test('vertical oscillation preserves gap and horizontal spacing inside world bounds',()=>{const g=game(()=>.05);g.api.start();for(const height of [270,384])for(const level of [25,50,125,300]){g.scene.setup({height,level});const pipe=g.scene.createPipe(400,80);assert.ok(pipe.motion);let previous=pipe.y;for(let i=0;i<500;i++){const oldY=pipe.y,oldBottom=pipe.y+pipe.gap;g.scene.updatePipeMotion(pipe,.03);assert.equal(pipe.x,400);assert.equal(pipe.gap,80);assert.ok(pipe.y>=24-1e-8&&pipe.y+pipe.gap<=height-28-24+1e-8);assert.ok(Math.abs((pipe.y-oldY)-(pipe.y+pipe.gap-oldBottom))<1e-8);if(i===150)assert.notEqual(pipe.y,previous);}}});
test('pause freezes actual pipe movement and restart removes moving pipes',()=>{const g=game(()=>0);g.api.start();g.scene.setup({level:25});const pipe=g.scene.createPipe(350,80);g.scene.setup({pipes:[pipe]});g.api.pause();const y=pipe.y,age=pipe.motion.age,x=pipe.x;g.scene.update(.03);assert.equal(pipe.y,y);assert.equal(pipe.motion.age,age);assert.equal(pipe.x,x);g.api.start();assert.equal(g.scene.inspect().pipes.length,0);assert.equal(g.api.getState().difficulty,0);});
test('pickups in moving gaps follow the pipe and stay inside throughout the oscillation',()=>{const g=game(()=>0);g.api.start();g.scene.setup({level:25});const pipe=g.scene.createPipe(350,80),pos=g.scene.pickupPosition(pipe);g.scene.setup({pipes:[pipe],pickups:[{kind:'bomb',phase:0,...pos}]});g.scene.update(.03);const pickup=g.scene.inspect().pickups[0];assert.equal(pickup.y,pipe.y+pickup.offset);for(let i=0;i<200;i++){g.scene.updatePipeMotion(pipe,.03);const y=pipe.y+pickup.offset;assert.ok(y-19>=pipe.y&&y+13<=pipe.y+pipe.gap);}g.scene.draw();});
test('collisions use the moving gap rather than its initial position',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird,pipe={x:b.x,y:45,gap:88,passed:false,motion:{baseY:85,amplitude:40,rate:Math.PI/.03,phase:-Math.PI/2,age:0}};assert.ok(b.y>pipe.y+7&&b.y<pipe.y+pipe.gap-7);g.scene.setup({pipes:[pipe]});g.scene.update(.03);assert.equal(g.api.getState().state,'dead');});
test('bombs destroy mobile pipes and detach their remaining pickups',()=>{const g=game(()=>0);g.api.start();g.scene.setup({level:25,bombs:1});const pipe=g.scene.createPipe(350,80),pos=g.scene.pickupPosition(pipe);g.scene.setup({pipes:[pipe],pickups:[{kind:'bomb',phase:0,...pos}]});assert.equal(g.api.detonate(),true);assert.equal(g.scene.inspect().pipes.length,0);g.scene.update(.01);assert.equal(g.scene.inspect().pickups[0].anchor,null);});
test('random pickups remain clear of moving pipe sweeps',()=>{let seed=79;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();for(const level of [25,75,150])for(const height of [270,384]){g.scene.setup({level,height});for(let i=0;i<25;i++){const a=g.scene.createPipe(300,80),b=g.scene.createPipe(476,80),p=g.scene.pickupPosition(b,a);if(!p)continue;if(p.placement==='gap'){assert.equal(p.anchor,b);continue;}assert.ok(p.y-19>=0&&p.y+13<height-28);for(let j=0;j<5;j++){g.scene.updatePipeMotion(a,.3);g.scene.updatePipeMotion(b,.3);assert.ok(p.x-13>a.x+41&&p.x+13<b.x-5);}}}});
test('collecting a bomb adds 10 points once without increasing difficulty',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({pipes:[],pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().score,10);assert.equal(g.api.getState().bombs,1);assert.equal(g.api.getState().difficulty,0);assert.equal(g.api.getState().moment,'amanecer');assert.equal(g.api.getState().pipesPassed,0);g.scene.update(0);assert.equal(g.api.getState().score,10);g.scene.setup({bombs:3,pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().score,10);assert.equal(g.scene.inspect().pickups.length,1);});
test('bonus scores cannot advance the world; only passed pipes trigger its milestones',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({score:9,passed:9,level:30,pipes:[],pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0},{kind:'slow',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().score,59);assert.equal(g.api.getState().pipesPassed,9);assert.equal(g.elements.get('pipes-count').textContent,'9');assert.equal(g.api.getState().difficulty,10.5);assert.equal(g.api.getState().moment,'amanecer');assert.equal(g.api.getState().background,'bosque');passPipe(g);assert.equal(g.api.getState().score,60);assert.equal(g.api.getState().pipesPassed,10);assert.equal(g.elements.get('pipes-count').textContent,'10');assert.equal(g.api.getState().difficulty,11.5);assert.equal(g.api.getState().moment,'día');assert.equal(g.api.getState().background,'bosque');for(let i=0;i<10;i++)passPipe(g);assert.equal(g.api.getState().score,70);assert.equal(g.api.getState().pipesPassed,20);assert.equal(g.api.getState().moment,'atardecer');assert.notEqual(g.api.getState().background,'bosque');});
test('pickup bonus points count toward the final record',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({pipes:[],pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0}]});g.scene.update(0);g.scene.setup({bird:{x:b.x,y:245,v:0}});g.scene.update(0);assert.equal(g.api.getState().state,'dead');assert.equal(g.api.getState().best,10);});
test('clock rarity boundaries choose weaker clocks more often',()=>{for(const [roll,expected] of [[0,'basic'],[.649,'basic'],[.651,'rare'],[.919,'rare'],[.921,'legendary'],[.999,'legendary']]){const g=game(()=>roll);assert.equal(g.scene.rollClockTier(),expected);}});
test('real spawned clocks follow the 65/27/8 rarity distribution',()=>{let seed=931;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();const counts={basic:0,rare:0,legendary:0};for(let i=0;i<400;i++){g.scene.setup({level:50,slowUnlocked:true,spawn:0,slowSpawn:0,bombSpawn:100,pipes:[],pickups:[]});g.scene.update(0);let p=g.scene.inspect().pickups[0];for(let retry=0;!p&&retry<5;retry++){g.scene.setup({spawn:0,pipes:[]});g.scene.update(0);p=g.scene.inspect().pickups[0];}assert.ok(p);assert.equal(p.kind,'slow');counts[p.clockTier]++;}assert.ok(Math.abs(counts.basic/400-.65)<.08);assert.ok(Math.abs(counts.rare/400-.27)<.08);assert.ok(Math.abs(counts.legendary/400-.08)<.06);assert.ok(counts.basic>counts.rare&&counts.rare>counts.legendary);});
test('each clock applies its own reduction, bonus and increasingly rich feedback',()=>{let previousParticles=0,previousDuration=0;for(const [id,steps,points] of [['basic',10,20],['rare',15,40],['legendary',30,60]]){const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({score:70,level:200,pipes:[],pickups:[{kind:'slow',clockTier:id,x:b.x,y:b.y,phase:0}]});const before=g.api.getState();g.scene.update(0);const after=g.api.getState();assert.equal(after.difficulty,200-3*steps);assert.ok(Math.abs(after.speedMultiplier-3*(1-steps/100))<1e-10);assert.equal(after.score,70+points);assert.equal(after.pipesPassed,before.pipesPassed);assert.equal(after.moment,before.moment);assert.equal(after.background,before.background);assert.equal(g.elements.get('bonus-points').textContent,'−'+steps+' %');assert.equal(g.elements.get('bonus-detail').textContent,'¡Velocidad reducida!');assert.equal(g.elements.get('bonus-extra').textContent,'+'+points+' PTS');const {particles,slowFeedback}=g.scene.inspect();assert.ok(particles.length>previousParticles);assert.ok(slowFeedback>previousDuration);previousParticles=particles.length;previousDuration=slowFeedback;}});
test('all clock rarities stop at baseline and report the actual reduction',()=>{for(const id of ['basic','rare','legendary']){const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({level:5,pipes:[],pickups:[{kind:'slow',clockTier:id,x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().speedMultiplier,1);assert.equal(g.api.getState().difficulty,0);assert.equal(g.elements.get('bonus-points').textContent,'−4,8 %');assert.equal(g.api.getState().score,{basic:20,rare:40,legendary:60}[id]);}});
test('clock rarity remains fixed after spawning and all sprites render',()=>{for(const [roll,id] of [[.1,'basic'],[.8,'rare'],[.95,'legendary']]){let value=roll;const g=game(()=>value);g.api.start();g.scene.setup({level:50,slowUnlocked:true,spawn:0,slowSpawn:0,bombSpawn:100,pipes:[],pickups:[]});g.scene.update(0);let p=g.scene.inspect().pickups[0];if(!p){value=.01;g.scene.setup({spawn:0,pipes:[]});g.scene.update(0);p=g.scene.inspect().pickups[0];}assert.ok(p);assert.equal(p.clockTier,id);value=.3;g.scene.draw();assert.equal(p.clockTier,id);assert.equal(g.scene.clockTier(p).id,id);}});
test('existing moving pipes adapt to higher difficulty without teleporting at the level change',()=>{const g=game(()=>.1);g.api.start();g.scene.setup({level:25});const pipe=g.scene.createPipe(400,80),before={y:pipe.y,amplitude:pipe.motion.amplitude,rate:pipe.motion.rate};g.scene.setup({level:125});g.scene.updatePipeMotion(pipe,0);assert.equal(pipe.y,before.y);assert.equal(pipe.motion.amplitude,before.amplitude);assert.equal(pipe.motion.rate,before.rate);for(let i=0;i<100;i++)g.scene.updatePipeMotion(pipe,.02);assert.ok(pipe.motion.amplitude>before.amplitude);assert.ok(pipe.motion.rate>before.rate);assert.equal(pipe.gap,80);});
test('clock reductions soften the motion of pipes already in flight',()=>{const g=game(()=>.1);g.api.start();g.scene.setup({level:100});const pipe=g.scene.createPipe(350,80),before={amplitude:pipe.motion.amplitude,rate:pipe.motion.rate},b=g.scene.inspect().bird;g.scene.setup({pipes:[pipe],pickups:[{kind:'slow',clockTier:'legendary',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().difficulty,40);for(let i=0;i<100;i++)g.scene.updatePipeMotion(pipe,.02);assert.ok(pipe.motion.amplitude<before.amplitude);assert.ok(pipe.motion.rate<before.rate);g.scene.setup({level:0});for(let i=0;i<400;i++)g.scene.updatePipeMotion(pipe,.02);assert.ok(pipe.motion.amplitude<.01);});
test('changing difficulty never changes the moving gap or pushes it past world bounds',()=>{const g=game(()=>.1);g.api.start();for(const height of [270,384]){g.scene.setup({height,level:25});const pipe=g.scene.createPipe(400,80);for(let i=0;i<1200;i++){g.scene.setup({level:[25,75,150,300,0][Math.floor(i/120)%5]});g.scene.updatePipeMotion(pipe,.02);assert.equal(pipe.gap,80);assert.equal(pipe.x,400);assert.ok(pipe.y>=24-1e-8&&pipe.y+pipe.gap<=height-28-24+1e-8);}}});
test('completed days advance only when night wraps to sunrise',()=>{const g=game();g.api.start();assert.equal(g.api.getState().days,1);assert.equal(g.elements.get('days-count').textContent,'1');for(let n=1;n<=80;n++){passPipe(g);assert.equal(g.api.getState().days,1+Math.floor(n/40));assert.equal(g.elements.get('days-count').textContent,String(1+Math.floor(n/40)));if(n===39||n===79)assert.equal(g.api.getState().moment,'noche');if(n%40===0)assert.equal(g.api.getState().moment,'amanecer');}});
test('pickup bonuses and clock reductions do not complete or undo days',()=>{const g=game();g.api.start();for(let n=0;n<39;n++)passPipe(g);const b=g.scene.inspect().bird;g.scene.setup({pipes:[],pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0},{kind:'slow',clockTier:'legendary',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().score,109);assert.equal(g.api.getState().days,1);assert.equal(g.api.getState().moment,'noche');passPipe(g);assert.equal(g.api.getState().days,2);collectSlow(g);assert.equal(g.api.getState().days,2);assert.equal(g.elements.get('days-count').textContent,'2');});
test('pause retains completed days and a new round resets their display',()=>{const g=game();g.api.start();for(let n=0;n<40;n++)passPipe(g);g.api.pause();g.scene.update(10);assert.equal(g.api.getState().days,2);assert.equal(g.elements.get('days-count').textContent,'2');g.api.start();assert.equal(g.api.getState().days,1);assert.equal(g.elements.get('days-count').textContent,'1');});

test('director builds recognizable sections with short rests and bounded height changes',()=>{const g=game(()=>.4),d=g.routes.createDirector();let previous=null;const seen=new Set();for(let i=0;i<45;i++){const p=d.next(270,60,76,163);seen.add(p.kind);if(i<3)assert.equal(p.kind,'rest');if(previous)assert.ok(Math.abs(p.center-previous.center)<=24.5+1e-8);if(p.kind==='rest'){assert.equal(p.gap,90);assert.equal(p.motionScale,0);}if(p.kind==='precision')assert.ok(p.gap>=69&&p.gap<72);assert.ok(p.spacing/163>=1.05);previous=p;}assert.deepEqual([...seen].sort(),['climb','dive','precision','rest']);d.reset();assert.equal(d.next(270,0,88,102).kind,'rest');});
test('generated main routes remain traversable without collecting any powerup',()=>{let seed=701;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();for(const height of [270,384])for(const level of [0,25,100,250]){g.scene.setup({height,level,pipes:[]});let previous=g.scene.plannedPipe(300);for(let i=0;i<24;i++){previous.x=300;g.scene.setup({pipes:[previous]});const pipe=g.scene.plannedPipe(300+previous.spacing),speed=102*(1+level*.01)*1.015;const path=g.routes.findRoute({previous,pipe,x:(previous.x+pipe.x)/2,y:null,height,speed,settings:g.scene.motionSettings(),birdX:g.scene.inspect().bird.x});assert.ok(path,'main route '+height+'/'+level+'/'+i);assert.ok(pipe.gap>=64);previous=pipe;}}});
test('off-route pickups have a reproducible flight path through the pickup and next opening',()=>{let seed=131;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();let checked=0;for(const height of [270,384])for(const level of [0,50,150]){g.scene.setup({height,level});const speed=102*(1+level*.01)*1.015;for(let i=0;i<12;i++){const gap=height>300?100:80,previous={x:300,y:height*.4-gap/2,gap},pipe={x:300+Math.max(176,speed*1.05),y:height*.46-gap/2,gap};const p=g.scene.pickupPosition(pipe,previous,3);if(!p||p.placement!=='between')continue;const path=g.routes.findRoute({previous,pipe,x:p.x,y:p.y,height,speed,settings:g.scene.motionSettings(),birdX:g.scene.inspect().bird.x});assert.ok(path);let collected=false;for(let j=1;j<path.length;j++){const a=path[j-1],b=path[j],dt=b.t-a.t;assert.ok(Math.abs(b.v-((b.flap?-145:a.v)+440*dt))<1e-7);assert.ok(Math.abs(b.y-(a.y+b.v*dt))<1e-7);assert.ok(b.y>7&&b.y<height-35);for(const obstacle of [previous,pipe])if(b.x+8>obstacle.x-5&&b.x-8<obstacle.x+41)assert.ok(b.y-6>=obstacle.y&&b.y+6<=obstacle.y+obstacle.gap);if(a.x<p.x&&b.x>=p.x)collected=Math.abs(b.y-p.y)<=10;}assert.ok(collected);checked++;}}assert.ok(checked>35);});
test('stronger clocks prefer larger reachable detours without making all pickups mandatory',()=>{const sums=[];for(const benefit of [0,3]){let seed=871;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();g.scene.setup({level:30});let total=0,count=0,gaps=0;for(let i=0;i<100;i++){const p=g.scene.pickupPosition({x:492,y:80,gap:88},{x:300,y:80,gap:88},benefit);if(p?.placement==='between'){total+=p.detour;count++;}if(p?.placement==='gap')gaps++;}assert.ok(count>60);assert.ok(gaps>0);sums.push(total/count);}assert.ok(sums[1]>sums[0]+5);});
test('unreachable detours defer a due clock while retaining its rarity',()=>{let value=.95;const g=game(()=>value);g.api.start();g.scene.setup({level:50,slowUnlocked:true,spawn:0,slowSpawn:0,bombSpawn:100,pipes:[],pickups:[]});g.scene.update(0);assert.equal(g.scene.inspect().pickups.length,0);assert.ok(g.scene.inspect().slowSpawn<=0);value=.01;g.scene.setup({spawn:0,pipes:[]});g.scene.update(0);assert.equal(g.scene.inspect().pickups[0].clockTier,'legendary');assert.ok(g.scene.inspect().slowSpawn>=24);});
test('a planned detour can be replayed in the actual game with moving pipes',()=>{for(const height of [270,384])for(const level of [50,150]){const g=game(()=>.5);g.api.start();g.scene.setup({height,level});const settings=g.scene.motionSettings(),speed=102*(1+level*.01),gap=84,spacing=Math.max(192,speed*1.05),baseY=height*.5-gap/2;const previous={x:300,y:baseY,gap,passed:true,motion:{baseY,amplitude:settings.amplitude*.65,scale:.65,rate:settings.rate*.65,phase:.5,age:0}},pipe={x:300+spacing,y:baseY,gap,passed:true,motion:{baseY,amplitude:settings.amplitude*.65,scale:.65,rate:settings.rate*.65,phase:1,age:0}};g.scene.updatePipeMotion(previous,0);g.scene.updatePipeMotion(pipe,0);const x=previous.x+spacing*.6,y=height*.5+18,path=g.routes.findRoute({previous,pipe,x,y,height,speed,settings,birdX:129});assert.ok(path);const obstacles=[previous,pipe].map(p=>({...p,motion:{...p.motion}}));for(const p of obstacles){let lead=path[0].t;while(lead>1e-8){const dt=Math.min(.01,lead);g.scene.updatePipeMotion(p,dt);lead-=dt;}}g.scene.setup({scrollSpeed:speed,pipes:obstacles,bird:{x:path[0].x,y:path[0].y,v:path[0].v},spawn:100,bombSpawn:100,pickups:[{kind:'bomb',x,y,phase:0}]});for(let i=1;i<path.length;i++){if(path[i].flap)g.api.flap();g.scene.update(path[i].t-path[i-1].t);assert.equal(g.api.getState().state,'playing');}assert.equal(g.api.getState().bombs,1);}});
test('fast mobile pickups appear ahead with time to react, never behind the bird',()=>{let seed=701;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.elements.get('frame').clientWidth=288;g.elements.get('frame').clientHeight=384;g.scene.resize();g.api.start();g.scene.setup({level:250,scrollSpeed:357});const b=g.scene.inspect().bird,pipe={x:303,y:130,gap:88},previous={x:-72,y:130,gap:88};let count=0;for(let i=0;i<40;i++){const p=g.scene.pickupPosition(pipe,previous,2);if(!p)continue;assert.ok(p.x>b.x);if(p.placement==='between')assert.ok((p.x-b.x)/(357*1.015)>=.3);count++;}assert.ok(count>5);});
test('bomb shield blocks a new imminent pipe for 0.9 active seconds then expires',()=>{const g=game();g.api.start();g.scene.setup({bombs:1,pipes:[],spawn:100});assert.ok(g.api.detonate());assert.equal(g.api.getState().shieldRemaining,.9);const b=g.scene.inspect().bird;g.scene.setup({pipes:[{x:b.x,y:b.y+30,gap:88,passed:false}]});g.scene.update(0);assert.equal(g.api.getState().state,'playing');assert.equal(g.scene.inspect().pipes.length,1);g.scene.setup({pipes:[]});for(let i=0;i<29;i++){g.scene.setup({bird:{x:b.x,y:b.y,v:0}});g.scene.update(.03);}assert.ok(g.api.getState().shieldRemaining>0);g.scene.draw();g.scene.setup({bird:{x:b.x,y:b.y,v:0},pipes:[{x:b.x,y:b.y+30,gap:88,passed:false}]});g.scene.update(.031);assert.equal(g.api.getState().state,'dead');assert.equal(g.api.getState().shieldRemaining,0);});
test('pause freezes shield duration and a restart clears it',()=>{const g=game();g.api.start();g.scene.setup({bombs:2});g.api.detonate();g.api.pause();g.scene.update(5);assert.equal(g.api.getState().shieldRemaining,.9);assert.equal(g.api.detonate(),false);g.api.pause();g.api.detonate();assert.equal(g.api.getState().shieldRemaining,.9);g.api.start();assert.equal(g.api.getState().shieldRemaining,0);assert.equal(g.elements.get('shield-status').hidden,true);});
test('shield never prevents ground or ceiling collisions, including reduced motion',()=>{for(const reduced of [false,true])for(const y of [3,245]){const g=game(null,{reduced});g.api.start();g.scene.setup({bombs:1});g.api.detonate();g.scene.draw();const b=g.scene.inspect().bird;g.scene.setup({bird:{x:b.x,y,v:0}});g.scene.update(0);assert.equal(g.api.getState().state,'dead');assert.equal(g.elements.get('shield-status').hidden,true);}});
test('results separate pipes and bonuses and retain peak speed after a clock',()=>{const g=game();g.api.start();for(let i=0;i<41;i++)passPipe(g);const b=g.scene.inspect().bird;g.scene.setup({pipes:[],pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0},{kind:'slow',clockTier:'legendary',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().speedMultiplier,1);assert.equal(g.api.getState().peakSpeed,1.41);g.scene.setup({bird:{x:b.x,y:245,v:0}});g.scene.update(0);for(const [id,value] of [['final-score','111'],['final-days','2'],['final-pipes','41'],['final-bonus','70'],['final-speed','×1,41'],['final-best','111'],['best-days','2'],['best-pipes','41'],['best-bonus','70'],['best-speed','×1,41']])assert.equal(g.elements.get(id).textContent,value);assert.equal(g.elements.get('bonus-breakdown').textContent,'Bombas 10 · Relojes 60 · Rasantes 0');for(const key of ['score','days','pipes','bonus','speed'])assert.equal(g.elements.get('record-'+key).hidden,false);assert.equal(g.api.getState().score,g.api.getState().pipesPassed+g.api.getState().bonusPoints);});
test('personal records persist across reloads and a zero-point run cannot overwrite them',()=>{const storage=new Map();let g=game(null,{storage});g.api.start();for(let i=0;i<40;i++)passPipe(g);const b=g.scene.inspect().bird;g.scene.setup({pipes:[],pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0}]});g.scene.update(0);g.scene.setup({bird:{x:b.x,y:245,v:0}});g.scene.update(0);g=game(null,{storage});assert.equal(g.api.getState().best,50);assert.equal(g.api.getState().records.days,2);assert.equal(g.api.getState().records.pipes,40);assert.equal(g.api.getState().records.bonus,10);assert.equal(g.api.getState().records.speed,1.4);g.api.start();assert.equal(g.api.getState().bonusPoints,0);assert.equal(g.api.getState().peakSpeed,1);g.scene.setup({bird:{x:125,y:245,v:0}});g.scene.update(0);assert.equal(g.elements.get('final-score').textContent,'0');assert.equal(g.elements.get('final-days').textContent,'1');assert.equal(g.elements.get('best-pipes').textContent,'40');for(const key of ['score','days','pipes','bonus','speed'])assert.equal(g.elements.get('record-'+key).hidden,true);assert.equal(g.api.getState().best,50);});
test('a pipe record is celebrated even without a new total-score record',()=>{const storage=new Map([['pixel-flight-best','200'],['pixel-flight-records-v1',JSON.stringify({days:1,pipes:10,bonus:100,speed:1.1})]]);const g=game(null,{storage});g.api.start();for(let i=0;i<11;i++)passPipe(g);g.scene.setup({bird:{x:125,y:245,v:0}});g.scene.update(0);assert.equal(g.elements.get('intro-tag').textContent,'¡NUEVO RÉCORD!');assert.equal(g.elements.get('record-score').hidden,true);assert.equal(g.elements.get('record-pipes').hidden,false);assert.equal(g.elements.get('final-best').textContent,'200');});
test('legacy score records survive missing or corrupt detailed records',()=>{for(const raw of ['invalid',JSON.stringify({days:-3,pipes:'bad',bonus:null,speed:-1})]){const g=game(null,{storage:new Map([['pixel-flight-best','111'],['pixel-flight-records-v1',raw]])});assert.equal(g.api.getState().best,111);assert.equal(g.api.getState().records.days,1);assert.equal(g.api.getState().records.pipes,0);g.api.start();g.scene.setup({bird:{x:125,y:245,v:0}});assert.doesNotThrow(()=>g.scene.update(0));assert.equal(g.elements.get('final-best').textContent,'111');}});
test('blocked storage still allows play, results and in-session records',()=>{const g=game(null,{denied:true});g.api.start();passPipe(g);g.scene.setup({bird:{x:125,y:245,v:0}});assert.doesNotThrow(()=>g.scene.update(0));assert.equal(g.elements.get('final-pipes').textContent,'1');assert.equal(g.api.getState().records.pipes,1);g.api.start();assert.equal(g.api.getState().records.pipes,1);});
test('new styles unlock during play, persist immediately, and equip only between runs',()=>{const storage=new Map();const g=game(null,{storage});assert.equal(g.api.selectCosmetic('bird','breeze'),false);g.api.start();for(let i=0;i<10;i++)passPipe(g);assert.equal(g.api.getState().collection.available,4);assert.equal(g.elements.get('unlock-name').textContent,'Pájaro Brisa');assert.equal(g.api.selectCosmetic('bird','breeze'),false);g.api.pause();assert.equal(g.api.selectCosmetic('bird','breeze'),false);g.api.pause();g.scene.setup({bird:{x:125,y:245,v:0}});g.scene.update(0);assert.equal(g.elements.get('run-unlocks').textContent,'Nuevo estilo: Pájaro Brisa');assert.equal(g.api.selectCosmetic('bird','breeze'),true);const reloaded=game(null,{storage});assert.equal(reloaded.api.getState().collection.selected.bird,'breeze');assert.equal(reloaded.api.getState().best,10);g.api.start();assert.equal(g.elements.get('unlock-toast').hidden,true);assert.equal(g.api.getState().collection.selected.bird,'breeze');});
test('cosmetic choices change particles but preserve flight, collisions, difficulty and random spawning',()=>{const games=[];for(let variant=0;variant<3;variant++){let seed=182;const storage=new Map([['pixel-flight-collection-v1',JSON.stringify({progress:{pipes:320,days:9,clean:100,clocks:10,bombs:30,gold:1}})]]);const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},{storage});if(variant){assert.ok(g.api.selectCosmetic('bird',variant===1?'aurora':'phoenix'));assert.ok(g.api.selectCosmetic('trail',variant===1?'stellar':'glacier'));assert.ok(g.api.selectCosmetic('blast',variant===1?'boreal':'supernova'));}g.api.start();g.scene.setup({level:35,bombs:1,scrollSpeed:130});g.api.flap();const tail=g.scene.inspect().particles.map(p=>p.color);g.api.detonate();const explosion=g.scene.inspect().blasts[0].colors;g.scene.draw();for(let i=0;i<140;i++){if(i%31===0)g.api.flap();g.scene.update(.02);}const s=g.api.getState(),p=g.scene.inspect();games.push({tail,explosion,physics:JSON.stringify({state:s.state,score:s.score,pipesPassed:s.pipesPassed,difficulty:s.difficulty,shield:s.shieldRemaining,bombs:s.bombs,bird:p.bird,pipes:p.pipes,pickups:p.pickups,speed:p.scrollSpeed})});}assert.equal(games[0].physics,games[1].physics);assert.equal(games[0].physics,games[2].physics);assert.notEqual(JSON.stringify(games[0].tail),JSON.stringify(games[1].tail));assert.notEqual(JSON.stringify(games[0].explosion),JSON.stringify(games[1].explosion));});
test('adversaries unlock after 35 actual pipes and bonus points cannot unlock them early',()=>{const g=game(()=>.5);g.api.start();const b=g.scene.inspect().bird;g.scene.setup({score:34,passed:34,level:40,enemySpawn:0,spawn:100,bombSpawn:100,pipes:[],pickups:[{kind:'bomb',x:b.x,y:b.y,phase:0},{kind:'slow',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().score,84);assert.equal(g.api.getState().enemiesUnlocked,false);assert.equal(g.api.getState().enemyCount,0);passPipe(g);assert.equal(g.api.getState().pipesPassed,35);assert.equal(g.api.getState().enemiesUnlocked,true);assert.equal(g.api.getState().enemyCount,1);g.scene.setup({level:0,enemies:[],enemySpawn:0,pipes:[]});g.scene.update(0);assert.equal(g.api.getState().enemyCount,1);});
test('adversaries warn first then fly left at a strictly constant height',()=>{const g=game(()=>.5);g.api.start();g.scene.setup({passed:35,level:35,spawn:100,bombSpawn:100});const e=g.scene.createEnemy();assert.ok(e);g.scene.setup({enemies:[e],enemySpawn:100});const x=e.x,y=e.y;g.scene.updateEnemies(.4,g.scene.inspect().bird.y);assert.equal(e.x,x);assert.ok(e.warning>0);g.scene.draw();for(let i=0;i<40;i++)g.scene.updateEnemies(.02,g.scene.inspect().bird.y);assert.equal(e.warning,0);assert.ok(e.x<x);assert.equal(e.y,y);g.scene.draw();});
test('bomb explosions preserve enemy objects and their warning/motion state',()=>{const g=game();g.api.start();const b=g.scene.inspect().bird,e={x:b.x+80,y:b.y,speed:180,warning:0,age:1},warning={x:502,y:30,speed:180,warning:.5,age:0};g.scene.setup({bombs:1,enemies:[e,warning],pipes:[{x:300,y:70,gap:88}]});assert.ok(g.api.detonate());assert.equal(g.scene.inspect().pipes.length,0);assert.equal(g.api.getState().enemyCount,2);assert.equal(g.scene.inspect().enemies[0],e);assert.equal(e.x,b.x+80);assert.equal(warning.warning,.5);assert.equal(g.api.getState().shieldRemaining,.9);});
test('enemy contact kills normally but not during bomb protection, including after it expires',()=>{for(const protectedRun of [false,true]){const g=game();g.api.start();const b=g.scene.inspect().bird,e={x:b.x,y:b.y,speed:150,warning:0,age:0};g.scene.setup({bombs:1,enemies:[e],spawn:100,bombSpawn:100});if(protectedRun)g.api.detonate();g.scene.updateEnemies(0,b.y);assert.equal(g.api.getState().state,protectedRun?'playing':'dead');assert.equal(g.scene.inspect().enemies.length,1);if(protectedRun){g.scene.setup({enemies:[]});for(let i=0;i<31;i++){g.scene.setup({bird:{x:b.x,y:b.y,v:0}});g.scene.update(.03);}assert.equal(g.api.getState().shieldRemaining,0);g.scene.setup({enemies:[{...e,x:b.x}]});g.scene.updateEnemies(0,b.y);assert.equal(g.api.getState().state,'dead');}}});
test('swept enemy collisions catch fast crossings without false hits at another height',()=>{for(const sameHeight of [false,true]){const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({enemies:[{x:b.x+80,y:b.y+(sameHeight?0:40),speed:6000,warning:0,age:0}]});g.scene.updateEnemies(.035,b.y);assert.equal(g.api.getState().state,sameHeight?'dead':'playing');}});
test('higher effective difficulty speeds up adversaries and increases their frequency, clocks soften both',()=>{const g=game();g.api.start();g.scene.setup({level:35});const initial=g.scene.enemySettings();g.scene.setup({level:150,scrollSpeed:255,passed:35,enemies:[{x:2000,y:30,speed:326,warning:0,age:0}],enemySpawn:100,spawn:100,bombSpawn:100});const harder=g.scene.enemySettings();assert.ok(harder.speed>initial.speed);assert.ok(harder.minInterval<initial.minInterval);assert.ok(harder.maxInterval<initial.maxInterval);assert.equal(initial.maxActive,1);assert.equal(harder.maxActive,2);const b=g.scene.inspect().bird;g.scene.setup({pickups:[{kind:'slow',clockTier:'legendary',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().difficulty,75);const easier=g.scene.enemySettings();assert.ok(easier.speed<harder.speed);assert.ok(easier.minInterval>harder.minInterval);const e=g.scene.inspect().enemies[0];for(let i=0;i<50;i++){g.scene.setup({bird:{x:b.x,y:b.y,v:0}});g.scene.update(.02);}assert.ok(e.speed<326);assert.equal(e.y,30);});
test('pause freezes enemy flight, warnings and spawn timers, restart clears them',()=>{const g=game();g.api.start();const e={x:350,y:30,speed:180,warning:.4,age:0};g.scene.setup({passed:35,enemies:[e],enemySpawn:3});g.api.pause();g.scene.update(5);assert.equal(e.x,350);assert.equal(e.warning,.4);assert.equal(g.scene.inspect().enemySpawn,3);g.api.start();assert.equal(g.api.getState().enemyCount,0);assert.equal(g.api.getState().enemiesUnlocked,false);});
