test('enemy intervals stay irregular and offscreen adversaries leave without awarding points',()=>{let seed=711;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});g.api.start();g.scene.setup({passed:35,level:50,spawn:100,bombSpawn:100});const intervals=new Set(),settings=g.scene.enemySettings(),b=g.scene.inspect().bird;for(let i=0;i<10;i++){g.scene.setup({enemies:[],enemySpawn:0});g.scene.updateEnemies(0,b.y);assert.equal(g.api.getState().enemyCount,1);const delay=g.scene.inspect().enemySpawn;assert.ok(delay>=settings.minInterval&&delay<=settings.maxInterval);intervals.add(delay);g.scene.inspect().enemies[0].x=-40;g.scene.updateEnemies(0,b.y);assert.equal(g.api.getState().enemyCount,0);}assert.ok(intervals.size>1);assert.equal(g.api.getState().score,0);assert.equal(g.api.getState().pipesPassed,35);assert.equal(g.api.getState().difficulty,50);});test('closing results restores a clean home while keeping records and selected rewards',()=>{const g=game();g.api.start();for(let i=0;i<10;i++)passPipe(g);g.scene.setup({bird:{x:125,y:245,v:0}});g.scene.update(0);assert.equal(g.api.getState().state,'dead');assert.equal(g.elements.get('close-results').hidden,false);assert.ok(g.api.selectCosmetic('bird','breeze'));const saved=JSON.stringify([...g.storage]);assert.equal(g.api.returnHome(),true);const s=g.api.getState();assert.equal(s.state,'ready');assert.equal(s.score,0);assert.equal(s.pipesPassed,0);assert.equal(s.difficulty,0);assert.equal(s.shieldRemaining,0);assert.equal(s.best,10);assert.equal(s.records.pipes,10);assert.equal(s.collection.selected.bird,'breeze');assert.equal(JSON.stringify([...g.storage]),saved);for(const key of ['pipes','enemies','pickups','particles','blasts'])assert.equal(g.scene.inspect()[key].length,0);for(const id of ['results','hud','close-results'])assert.equal(g.elements.get(id).hidden,true);assert.equal(g.elements.get('home-unlocks').hidden,false);assert.equal(g.elements.get('play-label').textContent,'A VOLAR');assert.equal(g.elements.get('days-count').textContent,'1');assert.equal(g.elements.get('pipes-count').textContent,'0');g.api.start();assert.equal(g.api.getState().state,'playing');assert.equal(g.api.getState().score,0);assert.equal(g.elements.get('home-unlocks').hidden,true);});
