test('near miss margin includes exactly 20 pixels beyond the collision boundary and excludes more',()=>{for(const separation of [31.99,32,32.01]){const g=game();g.api.start();const b=g.scene.inspect().bird;g.scene.setup({enemies:[{x:b.x+50,y:b.y+separation,speed:200,warning:0,age:0}]});g.scene.updateEnemies(.5,b.y);assert.equal(g.api.getState().score,separation<=32?25:0,'separation '+separation);}});
function audioProbe(){const events=[];class AudioContext{constructor(){this.currentTime=0;this.state='running';this.destination={};}createOscillator(){const event={};return{frequency:{setValueAtTime(v){event.frequency=v;},exponentialRampToValueAtTime(){}},connect(){},start(t){events.push({...event,time:t});},stop(){}};}createGain(){return{gain:{setValueAtTime(){},exponentialRampToValueAtTime(){}},connect(){}};}}return{events,AudioContext};}
test('empty bomb attempts sound once per key press or button click and leave gameplay untouched',()=>{const a=audioProbe(),g=game(null,{audioContext:a.AudioContext});g.api.start();a.events.length=0;const before=JSON.stringify(g.api.getState());assert.equal(g.elements.get('bomb').disabled,false);for(const code of ['KeyX','Enter','NumpadEnter']){const n=a.events.length;g.keydown(code);assert.equal(a.events.length,n+2);g.keydown(code,true);assert.equal(a.events.length,n+2);}g.elements.get('bomb').listeners.click({detail:0,preventDefault(){},stopPropagation(){}});assert.equal(a.events.length,8);assert.equal(a.events[0].frequency,180);assert.equal(a.events[1].frequency,120);assert.ok(a.events[1].time>a.events[0].time);assert.equal(JSON.stringify(g.api.getState()),before);assert.equal(g.scene.inspect().blasts.length,0);assert.equal(g.scene.inspect().particles.length,0);});
test('empty bomb feedback respects mute and stays silent outside active play',()=>{for(const muted of [false,true]){const a=audioProbe(),g=game(null,{audioContext:a.AudioContext,storage:new Map([['pixel-flight-muted',String(muted)]])});assert.equal(g.api.detonate(),false);assert.equal(a.events.length,0);g.api.start();a.events.length=0;g.api.detonate();assert.equal(a.events.length,muted?0:2);g.api.pause();a.events.length=0;g.api.detonate();assert.equal(a.events.length,0);assert.equal(g.elements.get('bomb').disabled,true);g.api.pause();g.scene.setup({bird:{x:125,y:245,v:0}});g.scene.update(0);a.events.length=0;g.api.detonate();assert.equal(a.events.length,0);}});
