test('restarting generates different opening pipes and powerup layouts at the same difficulty',()=>{let seed=84731;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});const openings=new Set(),pickups=new Set();for(let run=0;run<24;run++){g.api.start();g.scene.setup({level:40,spawn:0,bombSpawn:0,slowSpawn:100});g.scene.update(0);const p=g.scene.inspect().pipes[0];openings.add(p.y.toFixed(6));for(const item of g.scene.inspect().pickups)pickups.add(item.x.toFixed(3)+','+item.y.toFixed(3));assert.equal(g.api.getState().difficulty,40);assert.equal(g.api.getState().speedMultiplier,1.4);assert.equal(g.api.getState().pipesPassed,0);assert.equal(p.pattern,'rest');assert.equal(p.motion,undefined);}assert.ok(openings.size>=20);assert.ok(pickups.size>=10);});
test('randomized maps retain one of each challenge between regularly spaced rest sections',()=>{for(let seed=1;seed<=12;seed++){let value=seed;const g=game(),d=g.routes.createDirector(()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296;});const sections=[];for(let i=0;sections.length<13;i++){const p=d.next(270,60,76,163);if(!sections.length||sections.at(-1).kind!==p.kind)sections.push({kind:p.kind,count:1});else sections.at(-1).count++;}for(let i=0;i<12;i+=4){assert.equal(sections[i].kind,'rest');assert.equal(sections[i].count,3);assert.deepEqual(sections.slice(i+1,i+4).map(s=>s.kind).sort(),['climb','dive','precision']);for(const s of sections.slice(i+1,i+4))assert.ok(s.count===4||s.count===5);}}});
test('map variants retain difficulty gaps, bounded vertical steps, and minimum reaction time',()=>{let seed=72;const g=game(),d=g.routes.createDirector(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});for(const height of [270,384])for(const level of [0,25,100,300]){d.reset();const speed=102*(1+level*.01),gap=(height>300?104:88)-18*(1-Math.exp(-level*.024));let previous=null;for(let i=0;i<100;i++){const p=d.next(height,level,gap,speed);assert.ok(p.gap>=64);if(p.kind==='rest')assert.equal(p.gap,gap+14);else if(p.kind==='precision')assert.ok(p.gap>=Math.max(64,gap-7)&&p.gap<=Math.max(64,gap-4));else assert.equal(p.gap,gap);assert.ok(p.spacing>=speed*1.05);assert.ok(p.spacing>=(p.kind==='rest'?192:176));if(previous)assert.ok(Math.abs(p.center-previous.center)<=Math.min(34,20+level*.075)+1e-8);previous=p;}}});
test('narrower progression remains bounded and preserves moving-pipe limits',()=>{const g=game();g.api.start();for(const height of [270,384])for(const level of [0,24,25,50,100,200,1000]){g.api.start();g.scene.setup({height,level});const p=g.scene.plannedPipe(500),base=height>300?104:88,oldGap=base-18*(1-Math.exp(-level*.02));assert.equal(p.pattern,'rest');assert.ok(p.gap-14<=oldGap+1e-8);assert.ok(oldGap-(p.gap-14)<5);assert.ok(p.gap-14>=base-22);const m=g.scene.motionSettings();assert.equal(level<25?m.chance:0,0);assert.ok(m.chance<=.8&&m.amplitude<=40&&m.rate<=2.2);if(level>25){const n=level-25,oldRate=.7+1.5*(1-Math.exp(-n/90)),oldAmplitude=8+32*(1-Math.exp(-n/75));assert.ok(m.rate>=oldRate);assert.ok(m.rate<=oldRate*1.2);assert.ok(m.amplitude>=oldAmplitude);assert.ok(m.amplitude<=oldAmplitude*1.2);}assert.equal(g.api.getState().speedMultiplier,1+level*.01);}});
test('precision sections tighten gradually without shrinking rest sections or crossing the minimum gap',()=>{const g=game(),samples=[];for(const level of [0,50,150,1000]){const d=g.routes.createDirector(()=>.4);let precision=null;for(let i=0;i<20;i++){const p=d.next(270,level,70,102);if(p.kind==='rest'){assert.equal(p.gap,84);assert.equal(p.motionScale,0);}if(p.kind==='precision'){precision=p;break;}}assert.ok(precision);assert.ok(precision.gap>=64);samples.push(precision.gap);}assert.equal(samples[0],66);assert.ok(samples[1]<samples[0]);assert.ok(samples[2]<=samples[1]);assert.equal(samples[3],64);});
test('advanced landscapes stay locked before 40 actual pipes and remain available after clocks',()=>{let roll=.999;const g=game(()=>roll);g.api.start();for(let n=20;n<40;n+=20){g.world.advance(n);assert.ok(['bosque','montañas','ciudad','desierto','océano'].includes(g.world.getState().background));}g.api.start();for(let i=0;i<39;i++)passPipe(g);const b=g.scene.inspect().bird;g.scene.setup({pipes:[],pickups:[{kind:'slow',clockTier:'legendary',x:b.x,y:b.y,phase:0}]});g.scene.update(0);assert.equal(g.api.getState().score,99);assert.equal(g.api.getState().pipesPassed,39);assert.ok(['bosque','montañas','ciudad','desierto','océano'].includes(g.api.getState().background));passPipe(g);assert.equal(g.api.getState().background,'fondo del océano');g.scene.setup({level:0});for(let i=0;i<20;i++)passPipe(g);assert.equal(g.api.getState().background,'selva/pantano');g.api.start();assert.equal(g.api.getState().background,'bosque');});
test('all nine landscapes are eligible after 40 pipes and consecutive selections differ',()=>{let roll=.1;const g=game(()=>roll),names=['bosque','montañas','ciudad','desierto','océano','espacio exterior','planeta alienígena','selva/pantano','fondo del océano'];for(const target of names){g.world.reset();g.world.advance(40);const current=g.world.getState().background;if(current===target)g.world.advance(60);const options=names.filter(n=>n!==g.world.getState().background);roll=(options.indexOf(target)+.5)/options.length;const previous=g.world.getState().background;g.world.advance(80);assert.equal(g.world.getState().background,target);assert.notEqual(g.world.getState().background,previous);}});
test('new landscape drawings are distinct, finite, and render through every day phase on both layouts',()=>{let roll=.1;const g=game(()=>roll),signatures=new Set();for(const size of [[480,270],[288,384]])for(const phase of [0,1,2,3])for(let kind=5;kind<9;kind++){g.world.reset();roll=(kind-1+.5)/8;g.world.advance(phase===0?120:100);if(phase===1)g.world.advance(130);if(phase===3)g.world.advance(110);g.world.update(3);assert.equal(g.world.getState().moment,['amanecer','día','atardecer','noche'][phase]);const calls=[],ctx={fillStyle:'',save(){},restore(){},fillRect(...args){assert.ok(args.every(Number.isFinite));assert.ok(args[2]>=0&&args[3]>=0);calls.push([this.fillStyle,...args]);}};g.world.draw(ctx,...size,120);assert.ok(calls.length>100);if(phase===1&&size[0]===480)signatures.add(JSON.stringify(calls));}assert.equal(signatures.size,4);});
test('each advanced landscape has four distinct phases with a clearly darker night on both layouts',()=>{
  const rgb=color=>[1,3,5].map(i=>parseInt(color.slice(i,i+2),16));
  const light=color=>{const [r,g,b]=rgb(color);return .2126*r+.7152*g+.0722*b;};
  for(const size of [[480,270],[288,384]])for(let kind=5;kind<9;kind++){
    const skies=[],horizons=[];
    for(const points of [120,130,100,110]){
      const g=game(()=>(kind-1+.5)/8);g.world.reset();g.world.advance(points===120?120:100);if(points===130||points===110)g.world.advance(points);g.world.update(3);
      const fills=[],ctx={fillStyle:'',save(){},restore(){},fillRect(x,y,w,h){if(x===0&&w===size[0]&&y<size[1]-28)fills.push(this.fillStyle);}};
      g.world.draw(ctx,...size,120);skies.push(fills[0]);horizons.push(fills[Math.min(24,fills.length-1)]);
    }
    assert.equal(new Set(skies).size,4);assert.equal(new Set(horizons).size,4);
    assert.ok(light(skies[1])-light(skies[3])>20,`day/night contrast for biome ${kind}`);
  }
});
test('advanced phase transitions start at the displayed color, blend gradually, and survive interruption',()=>{
  for(let kind=5;kind<9;kind++){
    const g=game(()=>(kind-1+.5)/8);g.world.reset();g.world.advance(100);g.world.update(3);
    function sky(){let color;const ctx={fillStyle:'',save(){},restore(){},fillRect(){color??=this.fillStyle;}};g.world.draw(ctx,480,270,120);return color;}
    const dusk=sky();g.world.advance(130);assert.equal(sky(),dusk);g.world.update(.7);const partial=sky();assert.notEqual(partial,dusk);
    g.world.advance(150);assert.equal(sky(),partial);g.world.update(1);const mid=sky();assert.notEqual(mid,partial);g.world.update(1.5);const night=sky();assert.notEqual(night,mid);
    const channels=c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16));
    channels(mid).forEach((v,i)=>assert.ok(v>=Math.min(channels(partial)[i],channels(night)[i])&&v<=Math.max(channels(partial)[i],channels(night)[i])));
    g.world.update(0);assert.equal(sky(),night);
  }
});
test('whale swims toward its head, freezes on pause, and respects reduced motion',()=>{for(const reduced of [false,true]){const g=game(()=>.999,{reduced});g.api.start();g.world.advance(100);g.world.advance(130);g.world.update(3);function eye(){let position;const ctx={fillStyle:'',save(){},restore(){},fillRect(x,y,w,h){if(this.fillStyle==='#9bc3c6')position=[x,y,w,h];}};g.world.draw(ctx,480,270,120);assert.ok(position);return position;}const before=eye();g.world.update(1);const after=eye();if(reduced)assert.deepEqual(after,before);else{assert.ok(after[0]<before[0]);assert.ok(Math.abs(after[0]-before[0])<=6);assert.ok(Math.abs(after[1]-before[1])<=3);}g.api.pause();g.scene.update(.5);assert.deepEqual(eye(),after);}});
test('whale arrives visibly even late in a run and wraps only entirely outside either layout',()=>{
  for(const [width,height] of [[480,270],[288,384]]){
    const g=game(()=>.999);g.api.start();g.world.update(999);g.world.advance(100);g.world.advance(130);g.world.update(3);
    function eye(){let x;const ctx={fillStyle:'',save(){},restore(){},fillRect(xx){if(this.fillStyle==='#9bc3c6')x=xx;}};g.world.draw(ctx,width,height,120);return x;}
    let previous=eye(),wraps=0;assert.ok(previous>0&&previous<width);
    for(let i=0;i<200;i++){g.world.update(1);const current=eye();if(current>previous){wraps++;assert.ok(previous+220<0,'tail has left before wrapping');assert.ok(current-30>width,'head re-enters from beyond the right edge');}else assert.ok(current===previous-5);previous=current;}
    assert.ok(wraps>=1);
  }
});
test('flocks grow gradually, retain warnings and a replayable escape without bombs on both layouts',()=>{
  const sizes=new Set();let accepted=0;
  for(const [width,height] of [[480,270],[288,384]])for(const level of [60,180,300]){
    let seed=713+level;const g=game(()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});
    g.elements.get('frame').clientWidth=width;g.elements.get('frame').clientHeight=height;g.scene.resize();
    for(let n=0;n<12;n++){
      g.api.start();const speed=102*(1+level*.01),b=g.scene.inspect().bird;
      const gap=(height>300?104:88)-22*(1-Math.exp(-level*.027));
      const pipe={x:width*.72,y:height*.43-gap/2,gap,passed:true};
      g.scene.setup({level,passed:35,scrollSpeed:speed,pipes:[pipe],spawn:100,bombSpawn:100,slowSpawn:100,enemySpawn:0});
      if(n%2){const m=g.scene.motionSettings();pipe.motion={baseY:pipe.y,amplitude:m.amplitude*.65,scale:.65,rate:m.rate*.65,phase:.5,age:0};g.scene.updatePipeMotion(pipe,0);}
      g.scene.updateEnemies(0,b.y);
      const enemies=g.scene.inspect().enemies,settings=g.scene.enemySettings();
      assert.ok(enemies.length<=settings.maxActive);if(enemies.length<2)continue;
      sizes.add(enemies.length);accepted++;
      for(let i=0;i<enemies.length;i++){assert.equal(enemies[i].warning,.65);for(let j=0;j<i;j++)assert.ok(Math.abs(enemies[i].y-enemies[j].y)>=56);}
      const horizon=Math.max(...enemies.map(e=>e.warning+(e.x-b.x)/e.speed))+.65;
      const path=g.routes.findRoute({previous:null,pipe:null,x:b.x,y:null,height,speed,settings:g.scene.motionSettings(),startY:b.y,startV:b.v,birdX:b.x,horizon,obstacles:[pipe],hazards:enemies.map(e=>({...e,targetSpeed:settings.speed})),reaction:.18,minFlapInterval:.12});
      assert.ok(path);g.scene.setup({enemySpawn:100});let lastFlap=-Infinity;
      for(let i=1;i<path.length;i++){if(path[i].flap){assert.ok(path[i].t>=.18);assert.ok(path[i].t-lastFlap>=.12-1e-8);lastFlap=path[i].t;g.api.flap();}g.scene.update(path[i].t-path[i-1].t);assert.equal(g.api.getState().state,'playing',`${width}/${level}/${n}/${i}`);}
      assert.equal(g.api.getState().bombs,0);
    }
  }
  assert.ok(accepted>=6);assert.ok(sizes.has(2));assert.ok(sizes.has(3));
});
