function rocketAudioProbe(){
  const base=audioProbe(),sources=[],buffers=[],filters=[],gains=[];let disconnected=0;
  const parameter=()=>({value:0,setValueAtTime(){},linearRampToValueAtTime(){},exponentialRampToValueAtTime(){}});
  class AudioContext extends base.AudioContext{
    constructor(){super();this.sampleRate=48000;}
    createBuffer(channels,length,rate){const samples=new Float32Array(length),buffer={getChannelData:()=>samples};buffers.push({channels,length,rate,samples});return buffer;}
    createBufferSource(){const source={buffer:null,connect(){},disconnect(){disconnected++;},start(t){this.started=t;},stop(t){this.stopped=t;}};sources.push(source);return source;}
    createBiquadFilter(){const filter={type:'',Q:parameter(),frequency:parameter(),connect(){},disconnect(){disconnected++;}};filters.push(filter);return filter;}
    createGain(){const gain={gain:parameter(),connect(){},disconnect(){disconnected++;}};gains.push(gain);return gain;}
  }
  return{...base,AudioContext,sources,buffers,filters,gains,get disconnected(){return disconnected;}};
}
test('Tesla flap uses cached filtered air noise instead of the bird beep and releases its audio nodes',()=>{
  const a=rocketAudioProbe(),g=game(null,{audioContext:a.AudioContext,storage:rocketStorage()});g.api.start();a.events.length=0;
  g.api.flap();assert.equal(a.events.length,0);assert.equal(a.sources.length,1);assert.equal(a.buffers.length,1);assert.deepEqual(a.filters.map(f=>f.type),['bandpass','lowpass']);assert.equal(a.sources[0].stopped-a.sources[0].started,.26);
  const data=a.buffers[0].samples;assert.ok(data.every(n=>Number.isFinite(n)&&n>=-1&&n<=1));assert.ok(new Set(data.slice(0,100)).size>90);
  g.api.flap();assert.equal(a.buffers.length,1);assert.equal(a.sources.length,2);assert.equal(a.sources[0].buffer,a.sources[1].buffer);
  a.sources[0].onended();assert.equal(a.disconnected,5);g.api.pause();g.api.flap();assert.equal(a.sources.length,2);
});
test('rocket sound respects mute and unavailable audio while other birds retain their beep',()=>{
  const a=rocketAudioProbe(),storage=rocketStorage();storage.set('pixel-flight-muted','true');const muted=game(null,{audioContext:a.AudioContext,storage});muted.api.start();muted.api.flap();assert.equal(a.sources.length,0);assert.equal(a.events.length,0);
  const classic=game(null,{audioContext:a.AudioContext});classic.api.start();a.events.length=0;classic.api.flap();assert.equal(a.events.length,1);assert.equal(a.events[0].frequency,550);assert.equal(a.sources.length,0);
  const silent=game(null,{storage:rocketStorage()});silent.api.start();assert.doesNotThrow(()=>silent.api.flap());assert.equal(silent.scene.inspect().bird.v,-145);
});
